parameters.jsCode:
const payload = $json;
const containers = Array.isArray(payload.containers) ? payload.containers : [];
const timestamp = payload.timestamp ?? new Date().toISOString();
const summary = payload.summary ?? {};

const items = [];

for (const c of containers) {
  if (c?.expected !== true) {
    continue;
  }

  const name = String(c.name ?? '').trim();
  if (!name) {
    continue;
  }

  const state = String(c.state ?? 'unknown').toLowerCase();
  const health = c.health == null ? null : String(c.health).toLowerCase();
  const criticality = String(c.criticality ?? 'warning').toLowerCase();
  const restartCount = Number(c.restart_count ?? 0);
  const image = c.image ?? '';
  const missing = c.missing === true;

  let severity = 'info';
  let event = 'docker_healthy';
  let status = 'healthy';
  let shouldEmit = false;
  let requiresAttention = false;
  let message = `Container ${name} está operando normalmente.`;
  let suggestedAction = null;

  const severityFromCriticality = (() => {
    if (criticality === 'critical') return 'critical';
    if (criticality === 'error') return 'error';
    return 'warning';
  })();

  // Incident priority: dead > restarting > stopped/missing > unhealthy
  if (state === 'dead') {
    event = 'container_dead';
    status = 'active';
    severity = severityFromCriticality;
    shouldEmit = true;
    requiresAttention = true;
    message = `Container ${name} está marcado como dead pelo Docker.`;
    suggestedAction =
      `Investigar logs do container ${name} (docker logs ${name}) e a causa da falha. ` +
      'Não reiniciar automaticamente — Viny autoriza ações.';
  } else if (state === 'restarting') {
    event = 'container_restarting';
    status = 'degraded';
    severity = severityFromCriticality;
    shouldEmit = true;
    requiresAttention = true;
    message = `Container ${name} está em estado restarting (possível restart loop).`;
    suggestedAction =
      `Verificar logs e healthcheck de ${name}. Evitar restart em loop; investigar a causa raiz.`;
  } else if (missing || state === 'exited' || state === 'created' || state === 'paused') {
    event = 'container_stopped';
    status = 'active';
    severity = severityFromCriticality;
    shouldEmit = true;
    requiresAttention = true;
    message = missing
      ? `Container esperado ${name} não foi encontrado no Docker.`
      : `Container esperado ${name} não está em execução (state=${state}).`;
    suggestedAction =
      `Verificar se a parada de ${name} foi intencional. ` +
      'Consultar logs e dependências antes de qualquer remediação manual.';
  } else if (health === 'unhealthy') {
    event = 'container_unhealthy';
    status = 'degraded';
    severity = severityFromCriticality;
    shouldEmit = true;
    requiresAttention = true;
    message = `Container ${name} está running, mas o Docker healthcheck reportou unhealthy.`;
    suggestedAction =
      `Inspecionar healthcheck e logs de ${name}. Não reiniciar automaticamente.`;
  } else if (state === 'running' && (health === null || health === 'healthy' || health === 'starting')) {
    event = 'docker_healthy';
    status = 'healthy';
    severity = 'info';
    shouldEmit = false;
    requiresAttention = false;
    message =
      health === 'starting'
        ? `Container ${name} está running com healthcheck em starting.`
        : `Container ${name} está operando normalmente.`;
    suggestedAction = null;
  } else {
    // Estado inesperado
    event = 'container_stopped';
    status = 'active';
    severity = severityFromCriticality;
    shouldEmit = true;
    requiresAttention = true;
    message = `Container ${name} em estado inesperado: state=${state}, health=${health}.`;
    suggestedAction = `Investigar o estado do container ${name} no Docker (somente leitura).`;
  }

  items.push({
    json: {
      should_emit: shouldEmit,
      source: 'docker_guardian',
      severity,
      component: 'docker',
      event,
      status,
      timestamp,
      message,
      details: {
        container_name: name,
        container_state: state,
        container_health: health,
        image,
        restart_count: restartCount,
        restart_policy: c.restart_policy ?? null,
        project: c.project ?? null,
        service: c.service ?? null,
        criticality,
        has_healthcheck: c.has_healthcheck === true,
        missing,
        summary,
        previous_state: null,
        previous_health: null,
        notification_reason: null,
      },
      requires_attention: requiresAttention,
      suggested_action: suggestedAction,
    },
  });
}

return items;

const allItems = $input.all();
const results = [];

for (const item of allItems) {
  const data = item.json;

  const previousEvent = data.previous_event ?? null;
  const previousSeverity = data.previous_severity ?? null;
  const previousStatus = data.previous_status ?? null;

  let previousDetails = data.previous_details ?? null;
  if (typeof previousDetails === 'string') {
    try {
      previousDetails = JSON.parse(previousDetails);
    } catch (e) {
      previousDetails = null;
    }
  }

  const previousState = previousDetails?.container_state ?? null;
  const previousHealth = previousDetails?.container_health ?? null;
  const previousRestartCount =
    previousDetails?.restart_count === undefined || previousDetails?.restart_count === null
      ? null
      : Number(previousDetails.restart_count);

  const currentRestartCount = Number(data.details?.restart_count ?? 0);

  const details = {
    ...(data.details ?? {}),
    previous_state: previousState,
    previous_health: previousHealth,
  };

  let shouldNotify = false;
  let reason = 'no_change';
  let out = null;

  // 1. PRIMEIRO INCIDENTE
  if (previousEvent === null && data.should_emit === true) {
    shouldNotify = true;
    reason = 'first_incident';
  }

  // 2. RECUPERAÇÃO
  else if (
    data.event === 'docker_healthy' &&
    previousEvent !== null &&
    previousStatus !== 'healthy'
  ) {
    const name = details.container_name ?? 'container';
    out = {
      ...data,
      should_emit: true,
      severity: 'info',
      event: 'container_recovered',
      status: 'healthy',
      message:
        `Container ${name} voltou a operar normalmente. ` +
        `Incidente anterior: ${previousEvent}.`,
      requires_attention: false,
      suggested_action:
        'Nenhuma ação imediata necessária. Continuar monitorando a estabilidade do container.',
      details: {
        ...details,
        notification_reason: 'recovered',
      },
      notification: {
        should_notify: true,
        reason: 'recovered',
        previous_event: previousEvent,
        previous_severity: previousSeverity,
        previous_status: previousStatus,
      },
    };
  }

  // 3. AUMENTO DE RESTART_COUNT (sem outro incidente ativo)
  else if (
    data.should_emit !== true &&
    data.event === 'docker_healthy' &&
    previousRestartCount !== null &&
    Number.isFinite(previousRestartCount) &&
    currentRestartCount > previousRestartCount
  ) {
    const name = details.container_name ?? 'container';
    const criticality = details.criticality ?? 'warning';
    const severity =
      criticality === 'critical' ? 'critical' : criticality === 'error' ? 'error' : 'warning';

    out = {
      ...data,
      should_emit: true,
      severity,
      event: 'restart_count_increased',
      status: 'degraded',
      message:
        `Container ${name} teve aumento de restart_count ` +
        `(${previousRestartCount} → ${currentRestartCount}).`,
      requires_attention: true,
      suggested_action:
        `Investigar por que ${name} reiniciou. Conferir logs e política de restart — sem remediação automática.`,
      details: {
        ...details,
        notification_reason: 'first_incident',
      },
      notification: {
        should_notify: true,
        reason: previousEvent === 'restart_count_increased' ? 'incident_changed' : 'first_incident',
        previous_event: previousEvent,
        previous_severity: previousSeverity,
        previous_status: previousStatus,
      },
    };
  }

  // 4. MUDANÇA DO TIPO DE INCIDENTE
  else if (
    data.should_emit === true &&
    previousEvent !== null &&
    data.event !== previousEvent
  ) {
    shouldNotify = true;
    reason = 'incident_changed';
  }

  // 5. ESCALADA DE SEVERIDADE
  else if (
    data.should_emit === true &&
    previousEvent !== null &&
    data.event === previousEvent
  ) {
    const severityRank = {
      info: 1,
      warning: 2,
      error: 3,
      critical: 4,
    };

    const currentRank = severityRank[data.severity] ?? 0;
    const previousRank = severityRank[previousSeverity] ?? 0;

    if (currentRank > previousRank) {
      shouldNotify = true;
      reason = 'severity_escalated';
    }
  }

  if (out === null) {
    details.notification_reason = reason;
    out = {
      ...data,
      details,
      notification: {
        should_notify: shouldNotify,
        reason,
        previous_event: previousEvent,
        previous_severity: previousSeverity,
        previous_status: previousStatus,
      },
    };
  }

  results.push({ json: out });
}

return results;

parameters.jsonBody:
={{
{
  source: $json.source,
  severity: $json.severity,
  component: $json.component,
  event: $json.event,
  status: $json.status,
  timestamp: $json.timestamp,
  message: $json.message,
  details: {
    ...$json.details,
    notification_reason: $json.notification?.reason ?? $json.details?.notification_reason ?? null
  },
  requires_attention: $json.requires_attention,
  suggested_action: $json.suggested_action
}
}}
